/** Generated by scaffold-crud-pages. Query hooks for Badges.
 *
 * Every read is a `useQuery`, every write a `useMutation` that invalidates the
 * domain on success. Nothing here re-fetches by hand — the invalidation IS the
 * refresh, which is what keeps two screens from disagreeing about one record.
 */
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { qk } from '~/queries/keys';
import {
  fetchBadgesList,
  fetchBadgesById,
  createBadges,
  updateBadges,
  deleteBadges,
  type FetchBadgesListParams,
} from '~/services/httpServices/badgesService';
import type { CreateBadgesRequest, UpdateBadgesRequest } from '~/types/badges';

const DOMAIN = 'badges';

export function useBadgesList(params?: FetchBadgesListParams) {
  return useQuery({
    queryKey: qk.list(DOMAIN, params),
    queryFn: () => fetchBadgesList(params),
  });
}

export function useBadges(id: string | undefined) {
  return useQuery({
    queryKey: qk.detail(DOMAIN, id ?? ''),
    queryFn: () => fetchBadgesById(id as string),
    enabled: Boolean(id),
  });
}

export function useCreateBadges() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (body: CreateBadgesRequest) => createBadges(body),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}

export function useUpdateBadges() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: ({ id, body }: { id: string; body: UpdateBadgesRequest }) =>
      updateBadges(id, body),
    onSuccess: (_data, { id }) => {
      qc.invalidateQueries({ queryKey: qk.detail(DOMAIN, id) });
      qc.invalidateQueries({ queryKey: qk.list(DOMAIN) });
    },
  });
}

export function useDeleteBadges() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: (id: string) => deleteBadges(id),
    onSuccess: () => qc.invalidateQueries({ queryKey: qk.all(DOMAIN) }),
  });
}
